__NUXT_JSONP__("/de/school-calendar", {data:[{details:{slug:"de",pageTitle:"MLI Schulkalender | Mentor Language Institute",pageDescription:"The program strating date varies depending on F1 or Non F1 students.",title:"MLI Schulkalender (2025-2026)",calendar:[{year:"2026",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2026.PNG"},{year:"2027",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2027.png"}],notes:["\u003Cfont color=\"#FECC13\"\u003EGelb\u003C\u002Ffont\u003E: Studienbeginn (Modul)\u003Cbr \u002F\u003E\u003Cfont color=\"”#008000”\"\u003EGrün\u003C\u002Ffont\u003E: Keine Schule (Ferien)"],schoolCalendar:{title:"Schulkalender (Programmstartdaten)",description:["Das Startdatum des Programms variiert je nach F1- oder Nicht-F1-Studenten."],lists:[{key:"Nicht-F1-Studenten, die kein Studentenvisum erhalten.",value:["Kann ihr Programm an jedem Montag beginnen. \u003Cbr\u003E Wenn der Montag ein Feiertag ist, ist das Startdatum des Programms für diese Woche der Dienstag."]},{key:"F1-Studenten, die ein Studentenvisum erhalten.",value:["Kann an bestimmten Montagen beginnen. (im Kalender gelb markiert).","\u003C2026\u003E \u003Cbr \u002F\u003E1\u002F20, 2\u002F17, 3\u002F16, 4\u002F13, 5\u002F11, 6\u002F8, 7\u002F6, 8\u002F3, 8\u002F31, 9\u002F28, 10\u002F26, 11\u002F23, 12\u002F21","\u003C2027\u003E\u003Cbr \u002F\u003E 1\u002F25, 2\u002F22, 3\u002F22, 4\u002F19, 5\u002F17, 6\u002F14, 7\u002F12, 8\u002F9, 9\u002F7, 10\u002F4, 11\u002F1, 11\u002F29","\u003C2028\u003E \u003Cbr \u002F\u003E 1\u002F3"]}]},faq:{title:"Häufig gestellte Fragen zu Ankunftsdaten in den USA",lists:[{key:"\u003Cb\u003EWie viele Tage vor Beginn des Programms kann ein Student in die USA einreisen?\u003C\u002Fb\u003E",value:["MLI verlangt von unseren Schülern nicht, dass sie eine bestimmte Anzahl von Tagen im Voraus in die USA kommen. \u003Cbr\u003EUnsere Studenten reisen jedoch in der Regel 1 oder 2 Tage vor Beginn ihres Programms in die USA ein."],note:"Hinweis: Internationale Studenten dürfen 30 Tage vor Beginn ihres Programms in die USA einreisen."},{key:"\u003Cb\u003EIst es möglich, die Unterkunft vor Beginn des Programms zu beziehen?\u003C\u002Fb\u003E",value:["Ja. Wir können Ihr Einzugsdatum für Ihre Unterkunft beliebig arrangieren. \u003Cbr\u003EWenn Sie weitere Fragen haben, zögern Sie bitte nicht, uns zu konsultieren."]}]},dir:"\u002Fschool-calendar",path:"\u002Fschool-calendar\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:30.868Z",updatedAt:"2026-04-24T11:47:24.273Z"}}],fetch:{},mutations:void 0});